We sincerely thank the reviewer for the valuable feedback. We appreciate the time you spent on the paper. 

To take a careful look at the relationship of masked denoising score matching on observed data and score matching objective on complete data,
we can do the following decomposition:

\begin{equation}
\begin{aligned}
&\mathbb{E} _{p(\mathbf{x}^{\text{obs}}_0)}  \mathbb{E} _{p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}^{\text{obs}} _0)}[\|(\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t)-\nabla _{\mathbf{x}^{\text{obs}}_t} \log p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}^{\text{obs}}_0)) \odot \mathbf{m}\|_2^2]\\\\
=&\mathbb{E} _{p(\mathbf{x}^{\text{obs}}_t)}[\|(\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t) \odot \mathbf{m}\|_2^2] - 2\mathbb{E} _{p(\mathbf{x}^{\text{obs}}_0)}  \mathbb{E} _{p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}^{\text{obs}}_0)}[\langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t),\nabla _{\mathbf{x}^{\text{obs}}_t} \log p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}^{\text{obs}}_0)  \odot \mathbf{m}\rangle] +C,
\end{aligned}    
\end{equation}
where $C= \mathbb{E} _{p(\mathbf{x}^{\text{obs}}_t)}[\|\nabla _{\mathbf{x}^{\text{obs}}_t} \log p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}^{\text{obs}}_0) \odot \mathbf{m}\|_2^2]$ is independent with $\boldsymbol{\theta}$. We mainly look at the second term. We first replace $\nabla _{\mathbf{x}^{\text{obs}}_t} \log p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}^{\text{obs}}_0)  \odot \mathbf{m}$ by $\nabla _{\mathbf{x}(t)} \log p(\mathbf{x}(t) |\mathbf{x}(0)) \odot \mathbf{m}$, and we model the observe data $\mathbf{x}^{\text{obs}}_0=\mathbf{x}_0 \odot \mathbf{m}$, in this sense, we can build connection with score on complete data:
\begin{equation}
\begin{aligned}
&\mathbb{E} _{p(\mathbf{x}^{\text{obs}}_0)}  \mathbb{E} _{p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}^{\text{obs}}_0)}[\langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t), t),\nabla _{\mathbf{x}^{\text{obs}}_t} \log p(\mathbf{x}^{\text{obs}}_t\mid \mathbf{x}^{\text{obs}}_0)  \odot \mathbf{m}\rangle]\\\\
=&\mathbb{E} _{p(\mathbf{x}_0)}  \mathbb{E} _{p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}_0 \odot \mathbf{m})}[\langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t),\nabla _{\mathbf{x}_t} \log p(\mathbf{x}_t \mid \mathbf{x}_0)  \odot \mathbf{m}\rangle] \text{\ utilizing equality above} \\\\
=&\int   
\int p_0(\mathbf{x}_0) p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}_0 \odot \mathbf{m})\langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t), \nabla _{\mathbf{x}_t} \log p(\mathbf{x}_t \mid \mathbf{x}_0)  \odot \mathbf{m}\rangle \mathrm{d}\mathbf{x}_t \mathrm{d} \mathbf{x}_0 \\\\
=& \int
\int p_0(\mathbf{x}_0) \frac{p(\mathbf{x}^{\text{obs}}_t\mid \mathbf{x}_0 \odot \mathbf{m})}{p(\mathbf{x}_t \mid \mathbf{x}_0)}\langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t),  \nabla _{\mathbf{x}_t} p(\mathbf{x}_t \mid \mathbf{x}_0)  \odot \mathbf{m}\rangle \mathrm{d}\mathbf{x}_t  \mathrm{~d} \mathbf{x}_0,
\end{aligned}    
\end{equation}
where the ratio $\frac{p(\mathbf{x}^{\text{obs}}_t\mid \mathbf{x}_0 \odot \mathbf{m})}{p(\mathbf{x}_t\mid \mathbf{x}_0) }  = \frac{-\exp(\|\mathbf{x}^{\text{obs}}_t-\mathbf{x}_0 \odot \mathbf{m}\|_2^2) }{-\exp(\|\mathbf{x}_t -\mathbf{x}_0\|_2^2) }$, if the ratio is 1, we have
\begin{equation}
\begin{aligned}
&\mathbb{E} _{p(\mathbf{x}^{\text{obs}}_0)}  \mathbb{E} _{p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}^{\text{obs}}_0)}[\langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t),\nabla _{\mathbf{x}^{\text{obs}}_t} \log p(\mathbf{x}^{\text{obs}}_t \mid \mathbf{x}^{\text{obs}}_0)  \odot \mathbf{m}\rangle ]\\\\
=&   
\int  \langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t),     \frac{\mathrm{d} \int _{\mathbf{x}_0} p_0(\mathbf{x}_0) p(\mathbf{x}_t \mid \mathbf{x}_0) \mathrm{d} \mathbf{x}_0 }{\mathrm{d} \mathbf{x}_t} \odot \mathbf{m}\rangle  \mathrm{d}\mathbf{x}_t\\\\
=&   
 \int \langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t),   \frac{\mathrm{d} p_t(\mathbf{x}_t)  }{\mathrm{d} \mathbf{x}_t} \odot \mathbf{m}\rangle   \mathrm{d}\mathbf{x}_t\\\\
 =&   
 \int p_t(\mathbf{x}_t) \langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t),   \frac{\mathrm{d} \log p_t(\mathbf{x}_t)  }{\mathrm{d} \mathbf{x}_t} \odot \mathbf{m} \rangle  \mathrm{d} \mathbf{x}_t\\\\
=& \mathbb{E} _{p(\mathbf{x}^{\text{obs}}_t)}[\langle\mathbf{s} _{\boldsymbol{\theta}}(\mathbf{x}^{\text{obs}}_t, t),\nabla _{\mathbf{x}_t} \log p(\mathbf{x}_t)  \odot \mathbf{m}].
\end{aligned}    
\end{equation}
